class Solution {
    public int romanToInt(String s) {
        int total = 0;
        for (int index = 0; index < s.length(); index++) {
            total += value(s.charAt(index));
        }
        for (int index = 0; index + 1 < s.length(); index++) {
            if (value(s.charAt(index)) < value(s.charAt(index + 1))) {
                total -= 2 * value(s.charAt(index));
            }
        }
        return total;
    }

    private int value(char symbol) {
        switch (symbol) {
            case 'I': return 1;
            case 'V': return 5;
            case 'X': return 10;
            case 'L': return 50;
            case 'C': return 100;
            case 'D': return 500;
            default: return 1000;
        }
    }
}

